"use strict";(globalThis.webpackChunkmy_website||=[]).push([[15362],{35660(a){a.exports=JSON.parse('{"slug":"chang","title":"Chang","short":"The hard fork on September 1, 2024 that activated the Conway era and brought CIP-1694 governance live on Cardano.","category":"governance","aliases":["Chang 1","Chang Hard Fork"],"mentalModel":null,"related":["conway-era","plomin","van-rossem","cip-1694","hard-fork","hard-fork-initiation","voltaire"],"sources":[],"link":"/hardforks","level":"intermediate","body":"The Cardano hard fork that activated the Conway ledger era on September 1, 2024, switching on the first batch of on-chain governance features from CIP-1694: protocol parameter changes, hard-fork-initiation, and Info governance actions.\\n\\nLater Conway-era hard forks built on that foundation. [Plomin](/glossary/plomin) (January 2025) enabled the remaining governance actions such as treasury withdrawals and constitution updates, and [van Rossem](/glossary/van-rossem) (July 2026) was the first hard fork proposed and ratified entirely through the on-chain process Chang introduced. The next one, [Dijkstra](/glossary/dijkstra), moves Cardano into a new ledger era."}')}}]);